import type { ReactNode } from 'react';

export type IconName = 'activity' | 'check' | 'clock' | 'database' | 'file' | 'link' | 'lock' | 'search' | 'shield' | 'upload' | 'users' | 'warning';

const iconPaths: Record<IconName, ReactNode> = {
  activity: <><path d="M3 12h4l2-6 4 12 2-6h6" /></>,
  check: <path d="m5 12 4 4L19 6" />,
  clock: <><circle cx="12" cy="12" r="9" /><path d="M12 7v5l3 2" /></>,
  database: <><ellipse cx="12" cy="5" rx="8" ry="3" /><path d="M4 5v7c0 1.7 3.6 3 8 3s8-1.3 8-3V5M4 12v7c0 1.7 3.6 3 8 3s8-1.3 8-3v-7" /></>,
  file: <><path d="M6 2h8l4 4v16H6z" /><path d="M14 2v5h5M9 12h6M9 16h6" /></>,
  link: <><path d="M10 13a5 5 0 0 0 7.1 0l2-2a5 5 0 0 0-7.1-7.1l-1.1 1.1" /><path d="M14 11a5 5 0 0 0-7.1 0l-2 2A5 5 0 0 0 12 20.1l1.1-1.1" /></>,
  lock: <><rect x="5" y="10" width="14" height="11" rx="2" /><path d="M8 10V7a4 4 0 0 1 8 0v3" /></>,
  search: <><circle cx="11" cy="11" r="7" /><path d="m20 20-4-4" /></>,
  shield: <><path d="M12 2 20 5v6c0 5-3.4 9.2-8 11-4.6-1.8-8-6-8-11V5z" /><path d="m8.5 12 2.2 2.2 4.8-5" /></>,
  upload: <><path d="M12 16V4M7 9l5-5 5 5" /><path d="M5 15v5h14v-5" /></>,
  users: <><circle cx="9" cy="8" r="3" /><path d="M3 20c0-4 2.7-6 6-6s6 2 6 6" /><path d="M16 5a3 3 0 0 1 0 6M17 14c2.4.5 4 2.4 4 6" /></>,
  warning: <><path d="M12 3 2 21h20z" /><path d="M12 9v5M12 18h.01" /></>,
};

export function Icon({ name, size = 19 }: { name: IconName; size?: number }) {
  return <svg className="mc-icon" width={size} height={size} viewBox="0 0 24 24" aria-hidden="true">{iconPaths[name]}</svg>;
}

export function BrandMark() {
  return <span className="mc-brand-mark" aria-hidden="true"><span>+</span></span>;
}

export function Card({ children, className = '' }: { children: ReactNode; className?: string }) {
  return <article className={`mc-card ${className}`.trim()}>{children}</article>;
}

export function CardHeading({ icon, title, action }: { icon: IconName; title: string; action?: ReactNode }) {
  return <div className="mc-card-head"><h2 className="mc-card-title"><span className="mc-icon-circle"><Icon name={icon} size={16} /></span>{title}</h2>{action}</div>;
}

export function StatusBadge({ tone = 'primary', children }: { tone?: 'primary' | 'danger' | 'warning' | 'neutral' | 'success' | 'purple'; children: ReactNode }) {
  return <span className={`mc-badge mc-badge-${tone}`}><span className="mc-badge-dot" />{children}</span>;
}

export function SyncStatus({ state, lastUpdated }: { state: 'live' | 'stale' | 'offline'; lastUpdated?: string }) {
  const tone = state === 'live' ? 'success' : state === 'offline' ? 'danger' : 'warning';
  const label = state === 'live' ? 'Live' : state === 'offline' ? 'Offline' : 'Last-synced data';
  return <StatusBadge tone={tone}>{label}{lastUpdated ? ` · ${lastUpdated}` : ''}</StatusBadge>;
}

export function VerifiedOnChain({ lastSynced }: { lastSynced?: string }) {
  return <span className="mc-chain-badge"><Icon name="shield" size={15} /><span><strong>Verified on-chain</strong>{lastSynced ? <small>Last anchor {lastSynced}</small> : null}</span></span>;
}

export function Notice({ tone = 'info', title, children }: { tone?: 'info' | 'warning' | 'danger'; title: string; children: ReactNode }) {
  const icon = tone === 'danger' || tone === 'warning' ? 'warning' : 'shield';
  return <div className={`mc-notice mc-notice-${tone}`} role={tone === 'danger' ? 'alert' : 'status'}><span className="mc-notice-icon"><Icon name={icon} /></span><div><strong>{title}</strong><p>{children}</p></div></div>;
}

export function EmptyState({ icon, title, children }: { icon: IconName; title: string; children: ReactNode }) {
  return <div className="mc-empty"><span className="mc-icon-circle mc-icon-circle-large"><Icon name={icon} size={22} /></span><h2>{title}</h2><p>{children}</p></div>;
}
